def solution_deserialize(data):
    vals = iter(data.split(','))
    def dfs():
        v = next(vals)
        if v == 'N':
            return None
        node = TreeNode(int(v))
        node.left = dfs()
        node.right = dfs()
        return node
    return dfs()

